-- Asaa showcase catalog v1. Explicit execution only; never part of db reset/migrations.
-- Target reviewed: v0_database / nbhbendahduyiobyewzw, 2026-09-07 America/Tijuana.
-- Adds 6 banned, passwordless placeholder identities, 6 profiles/providers, 12 services.
-- No login credentials, payment records, reviews, balances, schema or policy changes.
-- A repeated import preserves existing demo content. Any UUID ownership collision aborts.
BEGIN;
DO $catalog$
DECLARE
  dataset constant text := 'asaa-showcase-v1';
  anchor constant timestamptz := '2026-09-07T12:00:00.000Z';
  disclaimer_ar constant text := 'هذه بيانات عرض خيالية، وليست خدمة متاحة للشراء. الأسعار والمواعيد والتقييمات أمثلة توضيحية؛ لا تمثل أعمالاً أو مؤهلات حقيقية.';
  disclaimer_en constant text := 'Fictional showcase data; this service is not available for purchase. Prices, delivery times and reviews are illustrative and do not represent real work or credentials.';
  catalog constant jsonb := $data$[{"category":"development","email":"asaa-demo-development@example.invalid","name_ar":"فريق مدار الرقمي — عرض تجريبي","name_en":"Madar Digital Studio — Demo","title_ar":"تطوير مواقع عربية وإنجليزية","title_en":"Arabic and English website development","bio_ar":"فريق خيالي يعمل على صفحات إطلاق المشاريع الصغيرة ولوحات المتابعة. يعرض هذا الملف كيفية الاتفاق على نطاق واضح، مراجعة نسخة أولية، ثم تسليم ملفات منظمة.","bio_en":"A fictional team focused on small-business launch pages and dashboards. This profile demonstrates a clear brief, a prototype review and an organized handover.","hourly_rate":180,"skills":["Next.js","Responsive UI","RTL / LTR","Accessible forms"],"services":[{"name_ar":"صفحة إطلاق ثنائية اللغة لمقهى جديد — عرض تجريبي","name_en":"Bilingual launch page for a new café — Demo","description_ar":"صفحة متجاوبة لمشروع المقهى الخيالي «فسحة»: نبذة، قائمة مختصرة، معرض صور ونموذج استفسار تجريبي. يبدأ العمل بمراجعة المحتوى، ثم تصميم الصفحة بالعربية والإنجليزية وتسليم الكود مع تعليمات التشغيل. تشمل جولة تعديلات واحدة؛ الاستضافة والنطاق وخدمة البريد خارج النطاق.","description_en":"A responsive page for the fictional Fusha café, with an introduction, a short menu, an image gallery and a demonstration enquiry form. The package covers a content review, Arabic and English layouts, and a code handover with setup notes. Includes one revision round; hosting, a domain and email delivery are outside the scope.","price":1800,"price_type":"fixed","delivery_time":"5 أيام عمل / 5 business days","features":["عربي وإنجليزي / Arabic and English","تصميم للجوال / Mobile layout","جولة تعديل واحدة / One revision round","الكود ودليل التشغيل / Source code and setup notes"]},{"name_ar":"لوحة متابعة حجوزات ببيانات تجريبية — عرض تجريبي","name_en":"Booking dashboard with sample data — Demo","description_ar":"واجهة لوحة متابعة تعرض حجوزات خيالية وحالاتها، مع البحث وتصفية الحالة وعرض ملخص يومي. مناسب لعرض فكرة المنتج على الفريق قبل تطوير التكاملات. التسليم نموذج يعمل ببيانات تجريبية؛ لا يشمل ربط بوابة دفع أو بيانات عملاء حقيقية.","description_en":"A dashboard prototype showing fictional bookings, status filters, search and a daily summary. It helps a team review the product idea before building integrations. The handover uses sample data and excludes payment integrations and real customer records.","price":2400,"price_type":"starting_from","delivery_time":"7 أيام عمل / 7 business days","features":["بحث وتصفية / Search and filters","ملخص يومي / Daily overview","حالات فارغة وتحميل / Empty and loading states","بيانات خيالية فقط / Fictional data only"]}]},{"category":"design","email":"asaa-demo-design@example.invalid","name_ar":"استوديو سطر — عرض تجريبي","name_en":"Satr Design Studio — Demo","title_ar":"هوية بصرية وتجارب استخدام","title_en":"Visual identity and user experience","bio_ar":"استوديو خيالي يوضح رحلة تصميم هوية بسيطة وواجهات قابلة للمراجعة. يركز العرض على مخرجات محددة وتوثيق قرارات اللون والخط، دون استخدام علامات تجارية أو أعمال عملاء حقيقيين.","bio_en":"A fictional studio demonstrating simple brand systems and reviewable interface designs. The showcase focuses on concrete deliverables and documented color and type choices, without using real client work or trademarks.","hourly_rate":160,"skills":["Figma","Brand systems","Prototyping","Arabic typography"],"services":[{"name_ar":"هوية مصغرة لمتجر حرفي — عرض تجريبي","name_en":"Mini identity for a craft shop — Demo","description_ar":"هوية أولية لمتجر «خيط» الخيالي تشمل اتجاهين للشعار، لوحة ألوان، اقتراح خط عربي وإنجليزي، وثلاثة قوالب منشورات. يختار العميل اتجاهاً واحداً لتطويره في جولتي مراجعة. التسليم ملفات SVG وPNG ودليل استخدام مختصر؛ تسجيل العلامة خارج النطاق.","description_en":"A starter identity for the fictional Khayt craft shop: two logo directions, a color palette, Arabic and English type suggestions, and three social post templates. One direction is developed over two review rounds. Deliverables are SVG and PNG assets and a short usage guide; trademark registration is outside the scope.","price":950,"price_type":"fixed","delivery_time":"4 أيام عمل / 4 business days","features":["اتجاهان للشعار / Two logo directions","ثلاثة قوالب / Three templates","جولتا مراجعة / Two review rounds","دليل مختصر / Short usage guide"]},{"name_ar":"تصميم خمس شاشات لحجز المواعيد — عرض تجريبي","name_en":"Five-screen appointment booking design — Demo","description_ar":"تصميم واجهة حجز مواعيد لمشروع خيالي: قائمة الخدمات، اختيار الموعد، تفاصيل العميل، المراجعة والتأكيد. يشمل نموذج Figma قابلاً للنقر ونسخة للجوال وملاحظات التسليم للمطور. لا يتضمن برمجة التطبيق أو اختبار مستخدمين ميدانياً.","description_en":"A booking flow for a fictional product: service selection, appointment time, customer details, review and confirmation. Includes a clickable Figma prototype, mobile layouts and developer handover notes. Application development and field user research are outside the scope.","price":1450,"price_type":"fixed","delivery_time":"6 أيام عمل / 6 business days","features":["خمس شاشات / Five screens","نموذج قابل للنقر / Clickable prototype","تخطيط RTL / RTL layout","ملاحظات للمطور / Developer handover"]}]},{"category":"marketing","email":"asaa-demo-marketing@example.invalid","name_ar":"فريق خطوة للمحتوى — عرض تجريبي","name_en":"Khatwa Content Team — Demo","title_ar":"تخطيط محتوى المشاريع الصغيرة","title_en":"Content planning for small businesses","bio_ar":"فريق خيالي يعرض طريقة تحويل أهداف مشروع صغير إلى تقويم محتوى واضح. الأرقام المقترحة في العرض ليست توقعات أداء، ولا يتضمن الملف نتائج حملات أو نسب نمو منسوبة لعملاء.","bio_en":"A fictional team showing how small-business goals become a practical content calendar. Suggested figures are not performance forecasts, and this profile makes no claims about client campaigns or growth results.","hourly_rate":120,"skills":["Content calendars","Audience briefs","Campaign planning","Arabic copy"],"services":[{"name_ar":"خطة محتوى أسبوعين لإطلاق مقهى — عرض تجريبي","name_en":"Two-week content plan for a café launch — Demo","description_ar":"خطة لإطلاق مقهى «فسحة» الخيالي: ثلاثة محاور محتوى، عشرة أفكار منشورات، أربعة نصوص فيديو قصيرة وتقويم نشر قابل للتعديل. تشمل جلسة مراجعة واحدة. لا يشمل السعر النشر أو التصوير أو ميزانية الإعلان، ولا توجد وعود بمبيعات أو وصول معين.","description_en":"A launch plan for the fictional Fusha café: three content themes, ten post ideas, four short-video scripts and an editable publishing calendar. Includes one review session. Posting, photography and advertising spend are excluded; no sales or reach outcome is promised.","price":650,"price_type":"fixed","delivery_time":"3 أيام عمل / 3 business days","features":["عشر أفكار منشورات / Ten post ideas","أربعة نصوص فيديو / Four video scripts","تقويم قابل للتعديل / Editable calendar","جلسة مراجعة / Review session"]},{"name_ar":"مراجعة محتوى صفحة تعريف المشروع — عرض تجريبي","name_en":"Business profile content review — Demo","description_ar":"مراجعة مكتبية لصفحة تعريف مشروع خيالي مع ملاحظات على وضوح الرسالة، ترتيب المعلومات ودعوات التواصل. التسليم قائمة أولويات وخمس صيغ بديلة للنصوص. يُحدد عدد الصفحات والوقت قبل البدء؛ لا تشمل الخدمة إدارة الحساب أو إعداد إعلانات.","description_en":"A desk review of a fictional business profile, covering message clarity, information order and contact prompts. Deliverables include a prioritized checklist and five alternative copy suggestions. Page count and time are agreed in advance; account management and ad setup are excluded.","price":120,"price_type":"hourly","delivery_time":"موعد متفق عليه / Scheduled session","features":["ملاحظات مرتبة / Prioritized notes","خمس صيغ بديلة / Five copy alternatives","ملخص بعد الجلسة / Session summary","النطاق يحدد مسبقاً / Scope agreed in advance"]}]},{"category":"writing","email":"asaa-demo-writing@example.invalid","name_ar":"استوديو حكاية — عرض تجريبي","name_en":"Hikaya Writing Studio — Demo","title_ar":"كتابة وتحرير عربي وإنجليزي","title_en":"Arabic and English writing and editing","bio_ar":"استوديو خيالي يكتب أوصاف منتجات ونصوص مواقع واضحة. توضح نماذج العرض حدود عدد الكلمات وآلية المراجعة، ولا تمثل ترجمة معتمدة أو استشارة متخصصة.","bio_en":"A fictional studio for clear product descriptions and website copy. Showcase packages demonstrate word limits and a review process; they are not certified translations or specialist advice.","hourly_rate":100,"skills":["Arabic editing","Product descriptions","Website copy","Plain language"],"services":[{"name_ar":"وصف عشرة منتجات لمتجر حرفي — عرض تجريبي","name_en":"Ten craft-store product descriptions — Demo","description_ar":"كتابة وصف عربي وإنجليزي لعشرة منتجات خيالية، حتى 80 كلمة لكل منتج في كل لغة. يتضمن كل وصف الاستخدام والخامات وطريقة العناية بناءً على موجز تجريبي متفق عليه. تشمل جولة تحرير واحدة؛ أي مواصفات واقعية يجب أن يقدمها صاحب المتجر ويعتمدها.","description_en":"Arabic and English descriptions for ten fictional products, up to 80 words per product in each language. Each covers use, materials and care based on an agreed sample brief. Includes one editing round; real product specifications would need to be supplied and approved by the shop owner.","price":450,"price_type":"fixed","delivery_time":"3 أيام عمل / 3 business days","features":["عشرة منتجات / Ten products","نسختان لكل وصف / Two language versions","حتى 80 كلمة / Up to 80 words each","جولة تحرير / One editing round"]},{"name_ar":"تحرير صفحة من نحن بالعربية — عرض تجريبي","name_en":"Arabic About Us page editing — Demo","description_ar":"تحرير مسودة عربية حتى 600 كلمة لمشروع خيالي، مع تحسين التسلسل والوضوح واقتراح عنوانين ومقدمة بديلة. التسليم نسخة بتعليقات ونسخة نهائية. يشمل جولة مراجعة واحدة، ولا يشمل اختراع قصة تأسيس أو أرقام إنجازات.","description_en":"Editing an Arabic draft of up to 600 words for a fictional project, improving flow and clarity and suggesting two headings and an alternative introduction. Includes an annotated draft, a clean final version and one revision. Invented founder stories and achievement figures are excluded.","price":280,"price_type":"fixed","delivery_time":"يومان عمل / 2 business days","features":["حتى 600 كلمة / Up to 600 words","تعليقات تحريرية / Editorial notes","نسخة نهائية / Clean final copy","جولة مراجعة / One revision round"]}]},{"category":"video","email":"asaa-demo-video@example.invalid","name_ar":"استوديو لقطة — عرض تجريبي","name_en":"Laqta Motion Studio — Demo","title_ar":"مونتاج فيديو قصير ورسوم متحركة","title_en":"Short-video editing and motion graphics","bio_ar":"استوديو خيالي يوضح خطوات إعداد فيديو قصير من لقطات يملكها العميل أو مواد مصرح بها. لا يتضمن العرض أسماء عملاء أو أعمالاً منشورة، وتستخدم جميع الطلبات سيناريوهات تجريبية.","bio_en":"A fictional studio demonstrating short-video production from client-owned or licensed assets. The profile includes no named clients or published portfolio claims; all orders use sample scenarios.","hourly_rate":150,"skills":["Video editing","Subtitles","Motion titles","Vertical video"],"services":[{"name_ar":"مونتاج فيديو تعريفي عمودي مدته 30 ثانية — عرض تجريبي","name_en":"30-second vertical introduction video — Demo","description_ar":"مونتاج فيديو لمبادرة خيالية من لقطات تجريبية يزود بها العميل، مع عناوين عربية وترجمة إنجليزية ونسخة عمودية. يشمل ترتيب المشاهد وتصحيحاً لونياً بسيطاً وجولة تعديل واحدة. التصوير والتعليق الصوتي وشراء الموسيقى خارج النطاق.","description_en":"An introduction video for a fictional initiative, edited from client-supplied sample footage with Arabic titles, English subtitles and a vertical export. Includes scene ordering, basic color adjustment and one revision. Filming, voice-over and music purchases are excluded.","price":800,"price_type":"fixed","delivery_time":"4 أيام عمل / 4 business days","features":["فيديو 30 ثانية / 30-second video","مقاس عمودي / Vertical format","عناوين وترجمة / Titles and subtitles","جولة تعديل / One revision round"]},{"name_ar":"ثلاث مقدمات متحركة للمنشورات — عرض تجريبي","name_en":"Three animated social post openers — Demo","description_ar":"ثلاث مقدمات متحركة قصيرة لهوية مشروع خيالي، مدة كل منها حتى خمس ثوانٍ. يعتمد التنفيذ على الشعار والألوان المعتمدة في الموجز. التسليم ملفات MP4 ونسخة بخلفية شفافة عند ملاءمة التصميم؛ لا يشمل تصميم شعار جديد.","description_en":"Three short animated openers for a fictional brand, each up to five seconds. Production follows the logo and colors agreed in the brief. Deliverables are MP4 files and a transparent-background version where the design supports it. A new logo design is excluded.","price":550,"price_type":"fixed","delivery_time":"3 أيام عمل / 3 business days","features":["ثلاث مقدمات / Three openers","حتى خمس ثوانٍ / Up to five seconds each","ملفات MP4 / MP4 exports","ألوان الموجز / Brief-based colors"]}]},{"category":"consulting","email":"asaa-demo-consulting@example.invalid","name_ar":"فريق بوصلة للتخطيط — عرض تجريبي","name_en":"Bousla Planning Team — Demo","title_ar":"تنظيم المشاريع والعمليات","title_en":"Project and operations planning","bio_ar":"فريق خيالي يساعد في عرض طريقة تنظيم نطاق مشروع صغير ومتابعة مهامه. المحتوى توضيحي عام، ولا يمثل استشارة قانونية أو مالية أو ادعاء بخبرة معتمدة.","bio_en":"A fictional team demonstrating how to scope a small project and track its tasks. The content is general and illustrative; it is not legal or financial advice and does not claim accredited expertise.","hourly_rate":220,"skills":["Project briefs","Process mapping","Task planning","Workshop notes"],"services":[{"name_ar":"جلسة تنظيم نطاق مشروع صغير — عرض تجريبي","name_en":"Small-project scoping session — Demo","description_ar":"جلسة تخطيط تجريبية مدتها ساعة لمناقشة أهداف مشروع خيالي وحدوده وأولوياته. التسليم موجز من صفحة واحدة وقائمة قرارات وخطوات تالية. السعر لساعة واحدة، وأي متابعة إضافية تحتاج اتفاقاً مستقلاً؛ لا تشمل الخدمة إعداد دراسة جدوى.","description_en":"A one-hour sample planning session to discuss a fictional project's goals, limits and priorities. Deliverables are a one-page brief, a decision log and next steps. The price covers one hour; extra follow-up needs a separate agreement. A feasibility study is excluded.","price":220,"price_type":"hourly","delivery_time":"موعد متفق عليه / Scheduled session","features":["جلسة ساعة / One-hour session","موجز صفحة واحدة / One-page brief","قائمة قرارات / Decision log","خطوات تالية / Next steps"]},{"name_ar":"خريطة استقبال طلبات العملاء — عرض تجريبي","name_en":"Customer enquiry intake process map — Demo","description_ar":"توثيق مسار استقبال استفسارات مشروع خيالي من الرسالة الأولى حتى إغلاق الطلب. يشمل مخططاً مبسطاً، خمس حالات للمتابعة وقالب رد أولي عربي وإنجليزي. لا يتضمن إعداد نظام CRM أو جمع بيانات عملاء حقيقية.","description_en":"Documenting how a fictional team handles enquiries from the first message to closure. Includes a simple process map, five tracking statuses and an initial-reply template in Arabic and English. CRM setup and collecting real customer information are excluded.","price":700,"price_type":"fixed","delivery_time":"3 أيام عمل / 3 business days","features":["مخطط عملية / Process map","خمس حالات متابعة / Five tracking statuses","قالب رد بلغتين / Bilingual reply template","ملاحظات تسليم / Handover notes"]}]}]$data$::jsonb;
  p jsonb; s jsonb; account_id uuid; provider_id_value uuid; service_id_value uuid;
  provider_index integer := 0; service_index integer := 0; new_identity boolean;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(dataset));
  FOR p IN SELECT value FROM jsonb_array_elements(catalog) LOOP
    provider_index := provider_index + 1;
    account_id := ('d3a00001-0000-4000-8000-' || lpad(provider_index::text,12,'0'))::uuid;
    provider_id_value := ('d3a00002-0000-4000-8000-' || lpad(provider_index::text,12,'0'))::uuid;
    IF EXISTS (SELECT 1 FROM auth.users u WHERE u.id=account_id AND
      (u.raw_app_meta_data->>'demo_dataset' IS DISTINCT FROM dataset OR u.email IS DISTINCT FROM p->>'email'
       OR coalesce(u.encrypted_password,'')<>'' OR u.banned_until IS DISTINCT FROM timestamptz '2099-01-01 00:00:00+00')) THEN
      RAISE EXCEPTION 'Demo identity collision or changed authentication: %', account_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.providers x WHERE x.id=provider_id_value AND x.user_id IS DISTINCT FROM account_id)
       OR EXISTS (SELECT 1 FROM public.providers x WHERE x.user_id=account_id AND x.id<>provider_id_value) THEN
      RAISE EXCEPTION 'Demo provider association collision: %', provider_id_value;
    END IF;
    new_identity := NOT EXISTS (SELECT 1 FROM auth.users WHERE id=account_id);
    IF new_identity THEN
      INSERT INTO auth.users(id,email,raw_app_meta_data,raw_user_meta_data,banned_until,created_at,updated_at)
      VALUES (account_id,p->>'email',jsonb_build_object('demo_dataset',dataset),
        jsonb_build_object('full_name',(p->>'name_ar')||' / '||(p->>'name_en'),'role','provider','demo_dataset',dataset),
        '2099-01-01 00:00:00+00',anchor,anchor);
      -- Supports both the reviewed legacy trigger and the fresh-schema trigger.
      INSERT INTO public.profiles(id,email,full_name,role,is_admin,avatar_url,created_at,updated_at)
      VALUES(account_id,p->>'email',(p->>'name_ar')||' / '||(p->>'name_en'),'provider',false,'/placeholder.svg',anchor,anchor)
      ON CONFLICT (id) DO NOTHING;
      UPDATE public.profiles SET role='provider',avatar_url='/placeholder.svg' WHERE id=account_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=account_id AND role='provider' AND NOT is_admin) THEN
      RAISE EXCEPTION 'Demo profile missing or unexpectedly privileged: %', account_id;
    END IF;
    INSERT INTO public.providers(id,user_id,name_ar,name_en,title_ar,title_en,bio_ar,bio_en,
      display_name,title,bio,category,hourly_rate,starting_price,skills,categories,avatar_url,
      rating,reviews_count,completed_projects,is_verified,tap_account_status,tap_onboarding_completed,created_at,updated_at)
    SELECT id,user_id,name_ar,name_en,title_ar,title_en,bio_ar,bio_en,display_name,title,bio,category,
      hourly_rate,starting_price,skills,categories,avatar_url,rating,reviews_count,completed_projects,is_verified,
      tap_account_status,tap_onboarding_completed,created_at,updated_at
    FROM jsonb_populate_record(NULL::public.providers,p || jsonb_build_object(
      'id',provider_id_value,'user_id',account_id,'display_name',p->>'name_en','title',p->>'title_en',
      'bio_ar',disclaimer_ar||chr(10)||chr(10)||(p->>'bio_ar'),'bio_en',disclaimer_en||chr(10)||chr(10)||(p->>'bio_en'),
      'bio',disclaimer_en||chr(10)||chr(10)||(p->>'bio_en'),'categories',jsonb_build_array(p->>'category'),
      'starting_price',(SELECT min((value->>'price')::numeric) FROM jsonb_array_elements(p->'services')),
      'avatar_url','/placeholder.svg','rating',0,'reviews_count',0,'completed_projects',0,'is_verified',false,
      'tap_account_status','not_connected','tap_onboarding_completed',false,'created_at',anchor,'updated_at',anchor))
    ON CONFLICT (id) DO NOTHING;
    FOR s IN SELECT value FROM jsonb_array_elements(p->'services') LOOP
      service_index := service_index + 1;
      service_id_value := ('d3a00003-0000-4000-8000-' || lpad(service_index::text,12,'0'))::uuid;
      IF EXISTS (SELECT 1 FROM public.services x WHERE x.id=service_id_value AND x.provider_id IS DISTINCT FROM provider_id_value) THEN
        RAISE EXCEPTION 'Demo service association collision: %',service_id_value;
      END IF;
      INSERT INTO public.services(id,provider_id,name_ar,name_en,description_ar,description_en,category,
        price,price_type,delivery_time,features,image_urls,is_active,created_at,updated_at)
      SELECT id,provider_id,name_ar,name_en,description_ar,description_en,category,
        price,price_type,delivery_time,features,image_urls,is_active,created_at,updated_at
      FROM jsonb_populate_record(NULL::public.services,s || jsonb_build_object(
        'id',service_id_value,'provider_id',provider_id_value,'category',p->>'category',
        'description_ar',disclaimer_ar||chr(10)||chr(10)||(s->>'description_ar'),
        'description_en',disclaimer_en||chr(10)||chr(10)||(s->>'description_en'),
        'image_urls',jsonb_build_array('/placeholder.svg'),'is_active',true,'created_at',anchor,'updated_at',anchor))
      ON CONFLICT (id) DO NOTHING;
    END LOOP;
  END LOOP;
  IF provider_index<>6 OR service_index<>12 THEN RAISE EXCEPTION 'Unexpected catalog size'; END IF;
END $catalog$;
COMMIT;
SELECT 'asaa-showcase-v1' AS dataset, count(DISTINCT u.id) AS demo_identities,
  count(DISTINCT p.id) AS demo_providers,count(s.id) AS demo_services
FROM auth.users u JOIN public.providers p ON p.user_id=u.id JOIN public.services s ON s.provider_id=p.id
WHERE u.raw_app_meta_data->>'demo_dataset'='asaa-showcase-v1';
